from collections import OrderedDict

def lru_cache_decorator(maxsize):
    def decorator(func):
        cache = OrderedDict()

        def wrapper(*args, **kwargs):
            key = args + tuple(sorted(kwargs.items()))

            if key in cache:
                value = cache.pop(key)
                cache[key] = value
                return value
            else:
                value = func(*args, **kwargs)
                cache[key] = value
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return value
        return wrapper
    return decorator
